(2768150, 384678, 64571, '<td valign="top">I haven''t voted on a sky or landscape yet, but this is great because it still leaves you guessing.  Great blacks, whites, and shadowing.</td>', 'I haven''t voted on a sky or landscape yet, but this is great because it still leaves you guessing.  Great blacks, whites, and shadowing.', '2006-08-28 15:25:28.000000', NULL, 1),
(2768153, 384450, 42100, '<td valign="top">This is some of most fascinating light play I''ve seen on DPC in quite some time.  Very intriguing photograph, beautiful!</td>', 'This is some of most fascinating light play I''ve seen on DPC in quite some time.  Very intriguing photograph, beautiful!', '2006-08-28 15:26:20.000000', NULL, 1),
(2768156, 386259, 42100, '<td valign="top">Very nice...the color tones are really what makes this photo appealing!</td>', 'Very nice...the color tones are really what makes this photo appealing!', '2006-08-28 15:27:39.000000', NULL, 1),
(2768164, 386710, 64571, '<td valign="top">Fantastic picture!!!!!!!!  My favorite - beautiful.</td>', 'Fantastic picture!!!!!!!!  My favorite - beautiful.', '2006-08-28 15:32:16.000000', NULL, 1),
(2768171, 384450, 64571, '<td valign="top">Beautiful picture, but I wouldn''t consider this subjectless - it''s a playground.  Love the picture and the mystical look!</td>', 'Beautiful picture, but I wouldn''t consider this subjectless - it''s a playground.  Love the picture and the mystical look!', '2006-08-28 15:35:23.000000', NULL, 1),
