(2771064, 385927, 58330, '<td valign="top">Fantastic shot, but does it fit the challenge?</td>', 'Fantastic shot, but does it fit the challenge?', '2006-08-29 17:25:23.000000', NULL, 1),
(2771072, 386397, 58330, '<td valign="top">I like the patterns on this close up, but I''m not saying what it is because that makes it have a subject and I''d feel a bit of a melon giving it a lower score for failing to meet the challenge requirements. So I''ll just score it as a no subject picture</td>', 'I like the patterns on this close up, but I''m not saying what it is because that makes it have a subject and I''d feel a bit of a melon giving it a lower score for failing to meet the challenge requirements. So I''ll just score it as a no subject picture', '2006-08-29 17:33:11.000000', NULL, 1),
(2771074, 386594, 58330, '<td valign="top">Nice image</td>', 'Nice image', '2006-08-29 17:34:46.000000', NULL, 1),
(2771095, 385802, 52713, '<td valign="top">love;y, but it has a subject.</td>', 'love;y, but it has a subject.', '2006-08-29 17:56:46.000000', NULL, 1),
