(2771153, 386661, 20941, '<td valign="top">good eye, great composition, wonderful for this challenge, technically sound, very cool work I really like it! 10</td>', 'good eye, great composition, wonderful for this challenge, technically sound, very cool work I really like it! 10', '2006-08-29 18:36:11.000000', NULL, 1),
(2771163, 386717, 20941, '<td valign="top">creative,fun, well photographed and gets your point across in a wonderfully artistic fashion. Outstanding!</td>', 'creative,fun, well photographed and gets your point across in a wonderfully artistic fashion. Outstanding!', '2006-08-29 18:40:04.000000', NULL, 1),
(2771176, 386731, 20941, '<td valign="top">good eye for a wonderful capture under great light conditions.  no difinitive subject and yet captivating, excellent entry</td>', 'good eye for a wonderful capture under great light conditions.  no difinitive subject and yet captivating, excellent entry', '2006-08-29 18:44:50.000000', NULL, 1),
(2771182, 386836, 20941, '<td valign="top">creative use of contrast to give depth to an image that may otherwise be just empty alley, now an interesting piece of art. very cool work</td>', 'creative use of contrast to give depth to an image that may otherwise be just empty alley, now an interesting piece of art. very cool work', '2006-08-29 18:49:08.000000', NULL, 1),
(2771196, 386696, 43088, '<td valign="top">Hmmm. Meets theme- definataly. <br/>Can''t say it is out of focus. <br/>Well exposed? The blacks were well captured and lighting is uniformly balanced. Nothing blown out. <br/>Originality? Definately unlike any other entries. <br/>Composition? Harder to judge. Small deduction on that, but perhaps I am being too picky there. 9.</td>', 'Hmmm. Meets theme- definataly. Can''t say it is out of focus. Well exposed? The blacks were well captured and lighting is uniformly balanced. Nothing blown out. Originality? Definately unlike any other entries. Composition? Harder to judge. Small deduction on that, but perhaps I am being too picky there. 9.', '2006-08-29 18:51:58.000000', NULL, 1),
(2771197, 386652, 43088, '<td valign="top">Looks over processed to me.</td>', 'Looks over processed to me.', '2006-08-29 18:52:37.000000', NULL, 1),
(2771202, 386259, 20941, '<td valign="top">fantastic work very well suited for this challenge</td>', 'fantastic work very well suited for this challenge', '2006-08-29 18:54:21.000000', NULL, 1),
(2771210, 386731, 31133, '<td valign="top">Very nice sky with tons of details. The high contrast sheep make a good pattern. For some reason, I wish they were a bit toned down in contrast though.  I might not have that feeling if it were possible to view this on a much larger scale. I doubt the small size we''re allowed here does this justice - seems like an image like this should be as big as a house. I like how the sky and the perceived size of the sheep work together to create a pattern that swirls towards the mountain on the horizon.</td>', 'Very nice sky with tons of details. The high contrast sheep make a good pattern. For some reason, I wish they were a bit toned down in contrast though.  I might not have that feeling if it were possible to view this on a much larger scale. I doubt the small size we''re allowed here does this justice - seems like an image like this should be as big as a house. I like how the sky and the perceived size of the sheep work together to create a pattern that swirls towards the mountain on the horizon.', '2006-08-29 18:57:28.000000', NULL, 1),
(2771211, 386715, 43088, '<td valign="top">Fits the theme perfect- it definately stands as an image on its own. Well done!</td>', 'Fits the theme perfect- it definately stands as an image on its own. Well done!', '2006-08-29 18:58:58.000000', NULL, 1),
(2771214, 386687, 31133, '<td valign="top">I took me a minute to realize what I was looking at - very funny! I can''t imagine meeting the challenge better than this. Wish the image held my interest more though, in some way. I''m not sure what it is, sorry ... possibly if there weren''t such a tight crop on either side vertically? I really don''t know. But I do think it''s a really clever take on the challenge. Good imagination!</td>', 'I took me a minute to realize what I was looking at - very funny! I can''t imagine meeting the challenge better than this. Wish the image held my interest more though, in some way. I''m not sure what it is, sorry ... possibly if there weren''t such a tight crop on either side vertically? I really don''t know. But I do think it''s a really clever take on the challenge. Good imagination!', '2006-08-29 19:01:06.000000', NULL, 1),
(2771215, 386343, 44980, '<td valign="top">Excellent execution and colors. Best of luck!</td>', 'Excellent execution and colors. Best of luck!', '2006-08-29 19:01:12.000000', NULL, 1),
(2771216, 386746, 31133, '<td valign="top">Such a dreamy, zen-like image. Love how the fog floats above the water - I always have loved this, and you''ve done a superb job of portraying it.</td>', 'Such a dreamy, zen-like image. Love how the fog floats above the water - I always have loved this, and you''ve done a superb job of portraying it.', '2006-08-29 19:03:01.000000', NULL, 1),
(2771217, 385927, 20941, '<td valign="top">fantastic composition and a wonderfully artistic entry well suited to this challenge. Very cool work!</td>', 'fantastic composition and a wonderfully artistic entry well suited to this challenge. Very cool work!', '2006-08-29 19:03:13.000000', NULL, 1),
(2771222, 386609, 31133, '<td valign="top">Even though I think I understand what you''re going for here, for me the strength of the patterns &amp; colors in the water compete too much with the vertical lines and green/red of the grass.</td>', 'Even though I think I understand what you''re going for here, for me the strength of the patterns & colors in the water compete too much with the vertical lines and green/red of the grass.', '2006-08-29 19:06:38.000000', NULL, 1),
(2771223, 385243, 20941, '<td valign="top">great eye for an interesting and eye catching subject well suited for this challenge and well photographed. really nice work!</td>', 'great eye for an interesting and eye catching subject well suited for this challenge and well photographed. really nice work!', '2006-08-29 19:07:56.000000', NULL, 1),
(2771228, 386831, 20941, '<td valign="top">wonderful tone with a captivating composition, fantastic capture!</td>', 'wonderful tone with a captivating composition, fantastic capture!', '2006-08-29 19:11:18.000000', NULL, 1),
(2771233, 385802, 31133, '<td valign="top">What a cutie! I really like the angle of the grass. I suppose you may get a bunch of "doesn''t meet the challenge" low scores, since this very sweet child is clearly a subject. I think this is a wonderful shot, however. My personal dnmc score only drops the score one point.</td>', 'What a cutie! I really like the angle of the grass. I suppose you may get a bunch of "doesn''t meet the challenge" low scores, since this very sweet child is clearly a subject. I think this is a wonderful shot, however. My personal dnmc score only drops the score one point.', '2006-08-29 19:13:03.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2771237, 386589, 31133, '<td valign="top">Beautiful! I like the duotone treatment a lot. This is a perfect example of an image without a subject that is still an extremely appealing image. The lighting is gorgeous, too - I like the darkness of it.</td>', 'Beautiful! I like the duotone treatment a lot. This is a perfect example of an image without a subject that is still an extremely appealing image. The lighting is gorgeous, too - I like the darkness of it.', '2006-08-29 19:15:37.000000', NULL, 1),
(2771238, 385294, 31133, '<td valign="top">Nice composition. The noise in the sky adds to the depth for me. This is definitely one of those kinds of images that requires more than a two second glance. The more I look at it, the more depth (nearly 3D) I see.</td>', 'Nice composition. The noise in the sky adds to the depth for me. This is definitely one of those kinds of images that requires more than a two second glance. The more I look at it, the more depth (nearly 3D) I see.', '2006-08-29 19:17:22.000000', NULL, 1),
(2771246, 383909, 31133, '<td valign="top">Wow! What a wonderful ghostly image there in the lower left. The crack in the wall and the other marks are very, very nice!</td>', 'Wow! What a wonderful ghostly image there in the lower left. The crack in the wall and the other marks are very, very nice!', '2006-08-29 19:20:59.000000', NULL, 1),
(2771249, 384678, 20941, '<td valign="top">outstanding image with dramatic tones, captivating and well presented, wonderful entry</td>', 'outstanding image with dramatic tones, captivating and well presented, wonderful entry', '2006-08-29 19:22:14.000000', NULL, 1),
