INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2775501, 385802, 35994, '<td valign="top">lol, cute picture, this could''ve worked in the "Simple Pleasures" challenge too!</td>', 'lol, cute picture, this could''ve worked in the "Simple Pleasures" challenge too!', '2006-08-30 17:15:02.000000', NULL, 1),
(2775701, 386230, 63544, '<td valign="top">excellent tones.</td>', 'excellent tones.', '2006-08-30 18:13:06.000000', NULL, 1),
(2775709, 386663, 52945, '<td valign="top">Meets the challenge well, but I don''t like the centered horizon, would be better to put it on either of the thirds lines.</td>', 'Meets the challenge well, but I don''t like the centered horizon, would be better to put it on either of the thirds lines.', '2006-08-30 18:14:56.000000', NULL, 1),
(2775710, 386246, 52945, '<td valign="top">The image is too busy for me.</td>', 'The image is too busy for me.', '2006-08-30 18:15:27.000000', NULL, 1),
(2775716, 386578, 52945, '<td valign="top">Great shot, I really like the symmetry. This is one of the rare occasions a centred horizon actually works. You''ve really managed to capture the texture in the clouds.</td>', 'Great shot, I really like the symmetry. This is one of the rare occasions a centred horizon actually works. You''ve really managed to capture the texture in the clouds.', '2006-08-30 18:17:23.000000', NULL, 1),
(2775726, 386311, 52945, '<td valign="top">This is a really good portrait. You can see the pain in his face, the emotion contrasts well with the skull tattoos. What bugs me is the mask (?) in the background. The photo would be even better if it was removed, or shot from a slightly different angle.</td>', 'This is a really good portrait. You can see the pain in his face, the emotion contrasts well with the skull tattoos. What bugs me is the mask (?) in the background. The photo would be even better if it was removed, or shot from a slightly different angle.', '2006-08-30 18:20:06.000000', NULL, 1),
(2775729, 386686, 52945, '<td valign="top">Nice display of textures.</td>', 'Nice display of textures.', '2006-08-30 18:20:40.000000', NULL, 1),
(2775734, 386669, 52945, '<td valign="top">I''m interested to know how this was done within the rules.</td>', 'I''m interested to know how this was done within the rules.', '2006-08-30 18:23:07.000000', NULL, 1),
(2775738, 386765, 52945, '<td valign="top">Nice image, but I don''t feel it really meets the challenge. To me the road is clearly the main subject of the image.</td>', 'Nice image, but I don''t feel it really meets the challenge. To me the road is clearly the main subject of the image.', '2006-08-30 18:24:05.000000', NULL, 1),
(2775741, 386848, 52945, '<td valign="top">I like the repetition and the curved flowing lines.</td>', 'I like the repetition and the curved flowing lines.', '2006-08-30 18:25:00.000000', NULL, 1),
(2775743, 386662, 52945, '<td valign="top">This is a great abstract image.</td>', 'This is a great abstract image.', '2006-08-30 18:25:31.000000', NULL, 1),
(2775748, 386571, 52945, '<td valign="top">Nice sunset. Highly saturated, bordering on overdone, but still looks good. The rock stands out, but not enough to be the subject, so this meets the challenge well.</td>', 'Nice sunset. Highly saturated, bordering on overdone, but still looks good. The rock stands out, but not enough to be the subject, so this meets the challenge well.', '2006-08-30 18:26:52.000000', NULL, 1),
(2775834, 386740, 28097, '<td valign="top">i love how you achieved a very wide angle but maintating a horizontal straight horizon...<br/>great colors and tone.. matches perfectly with the challenge.. great job.. 10</td>', 'i love how you achieved a very wide angle but maintating a horizontal straight horizon...great colors and tone.. matches perfectly with the challenge.. great job.. 10', '2006-08-30 18:53:25.000000', NULL, 1),
