INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2780356, 383653, 46330, '<td valign="top">I like the bokeh of the out of focus carpet in the upper left but the jeans don''t complement it very well.  Replacing the jeans with the red cushion you appear to be sitting on in the composition would have been a more effective contrast.</td>', 'I like the bokeh of the out of focus carpet in the upper left but the jeans don''t complement it very well.  Replacing the jeans with the red cushion you appear to be sitting on in the composition would have been a more effective contrast.', '2006-08-31 23:20:55.000000', NULL, 1),
(2780357, 385936, 46330, '<td valign="top">I think I can see the thought here, but the execution is off.  The shot is very noisy and soft, and I really dislike the red filter.</td>', 'I think I can see the thought here, but the execution is off.  The shot is very noisy and soft, and I really dislike the red filter.', '2006-08-31 23:21:04.000000', NULL, 1),
(2780359, 386669, 46330, '<td valign="top">I''m afraid this just looks more like a computer graphic from about 1985 than a photo.  If that''s what you wanted, then fine, but it''s just not too interesting.</td>', 'I''m afraid this just looks more like a computer graphic from about 1985 than a photo.  If that''s what you wanted, then fine, but it''s just not too interesting.', '2006-08-31 23:21:11.000000', NULL, 1),
(2780362, 384220, 41047, '<td valign="top">nice color composition.</td>', 'nice color composition.', '2006-08-31 23:21:48.000000', NULL, 1),
(2780367, 385802, 46330, '<td valign="top">This is a great photo, but it has a definite subject.</td>', 'This is a great photo, but it has a definite subject.', '2006-08-31 23:23:05.000000', NULL, 1),
(2780368, 383909, 41047, '<td valign="top">i like the composition a lot. nice minimalism.</td>', 'i like the composition a lot. nice minimalism.', '2006-08-31 23:23:13.000000', NULL, 1),
(2780370, 386710, 41047, '<td valign="top">i like the silvery tones.</td>', 'i like the silvery tones.', '2006-08-31 23:23:25.000000', NULL, 1),
