(2780425, 386397, 30982, '<td valign="top">It''s a melon, right?  Neat abstract.</td>', 'It''s a melon, right?  Neat abstract.', '2006-08-31 23:35:45.000000', NULL, 1),
(2780511, 386740, 39349, '<td valign="top">Awesome, into my favs. Love everything about this, the color composition, EVERYTHING! Did you use a graduated ND filter on this? Looks amazing! 10 from me.</td>', 'Awesome, into my favs. Love everything about this, the color composition, EVERYTHING! Did you use a graduated ND filter on this? Looks amazing! 10 from me.', '2006-09-01 00:03:49.000000', NULL, 1),
(2780525, 386343, 39349, '<td valign="top">You have to tell me what this is after the challenge. I''m guessing some kind of sea urchin or along those lines. Wonderful colors, composition and perfect lighting. 10 from me and into my favs.</td>', 'You have to tell me what this is after the challenge. I''m guessing some kind of sea urchin or along those lines. Wonderful colors, composition and perfect lighting. 10 from me and into my favs.', '2006-09-01 00:07:32.000000', NULL, 1),
(2780600, 386409, 50695, '<td valign="top">creative interpretation of the challenge, but also a literal fulfillment of the challenge. the eye is drawn to the "subject" but then immediately drawn out of frame, or the eye relaxes and takes in the lovely shapes of light in the overall composition. 10</td>', 'creative interpretation of the challenge, but also a literal fulfillment of the challenge. the eye is drawn to the "subject" but then immediately drawn out of frame, or the eye relaxes and takes in the lovely shapes of light in the overall composition. 10', '2006-09-01 00:24:48.000000', NULL, 1),
(2780612, 386798, 50695, '<td valign="top">sharp yet painterly at the same time. the composition allows nothing to be the subject. eminently tangible yet ultimately elusive.</td>', 'sharp yet painterly at the same time. the composition allows nothing to be the subject. eminently tangible yet ultimately elusive.', '2006-09-01 00:26:34.000000', NULL, 1),
(2780658, 386683, 50695, '<td valign="top">love love love the tones. as beautiful as an abstract painting, a Japanese print kind of beauty. 10</td>', 'love love love the tones. as beautiful as an abstract painting, a Japanese print kind of beauty. 10', '2006-09-01 00:36:34.000000', NULL, 1),
(2780672, 383909, 50695, '<td valign="top">love the smudged out humanity in front of the bare gritty wall. the extreme lefthand placement of the person has him competing with the spot above him and the crack behind him for viewer attention. therefore, a truly subjectless picture. 10</td>', 'love the smudged out humanity in front of the bare gritty wall. the extreme lefthand placement of the person has him competing with the spot above him and the crack behind him for viewer attention. therefore, a truly subjectless picture. 10', '2006-09-01 00:38:41.000000', NULL, 1),
(2780719, 386789, 50695, '<td valign="top">I could see this in an art gallery by a mixed media artist. beautiful, mysterious, infinite. 10</td>', 'I could see this in an art gallery by a mixed media artist. beautiful, mysterious, infinite. 10', '2006-09-01 00:49:59.000000', NULL, 1),
(2780730, 386778, 50695, '<td valign="top">that unreadable, doubled sign is a symbol (sign) of how we want a subject, a meaning. but the water drowns all meaning. it''s fascinating to see clearly that there IS a meaning there, but it is unavailable to us. 10</td>', 'that unreadable, doubled sign is a symbol (sign) of how we want a subject, a meaning. but the water drowns all meaning. it''s fascinating to see clearly that there IS a meaning there, but it is unavailable to us. 10', '2006-09-01 00:52:54.000000', NULL, 1),
(2780735, 385306, 50695, '<td valign="top">a lovely dark nothingness. I like how you frame the nothing on the top but not the bottom. I also love the two very different but still sensual textures of the framing elements. I also love the gradual darkening into the main nothingness. 10</td>', 'a lovely dark nothingness. I like how you frame the nothing on the top but not the bottom. I also love the two very different but still sensual textures of the framing elements. I also love the gradual darkening into the main nothingness. 10', '2006-09-01 00:54:04.000000', NULL, 1),
(2780741, 383942, 50695, '<td valign="top">that is such a fantastic shadow. I would even venture so far to say that it demands to be the subject of this complex composition, and therefore technically you are dnmc. So here''s my 10 for a dnmc!</td>', 'that is such a fantastic shadow. I would even venture so far to say that it demands to be the subject of this complex composition, and therefore technically you are dnmc. So here''s my 10 for a dnmc!', '2006-09-01 00:55:25.000000', NULL, 1),
(2780746, 386851, 50695, '<td valign="top">love the semi-focus and the old style black and white feel. a truly haunting abstract. something sad and desperate about it. 10</td>', 'love the semi-focus and the old style black and white feel. a truly haunting abstract. something sad and desperate about it. 10', '2006-09-01 00:56:59.000000', NULL, 1),
(2780750, 384678, 50695, '<td valign="top">A winslow homer painting without the ship! brilliant execution of the challenge. I hope this ribbons. I assume this is all clouds(?) but you''ve managed to turn it into sky and sea. fantastic. 10</td>', 'A winslow homer painting without the ship! brilliant execution of the challenge. I hope this ribbons. I assume this is all clouds(?) but you''ve managed to turn it into sky and sea. fantastic. 10', '2006-09-01 00:58:24.000000', NULL, 1),
(2780763, 384927, 50695, '<td valign="top">dead-on composition of competing elements. rich yet muted colors. and of course a shimmering veneer to it all! 10</td>', 'dead-on composition of competing elements. rich yet muted colors. and of course a shimmering veneer to it all! 10', '2006-09-01 01:00:27.000000', NULL, 1),
(2782541, 386562, 21430, '<td valign="top">This is a really fantastic shot, yet it feels like the whole image itself is the subject. Maybe I just have a different interpretation of what "Without Subject" means.</td>', 'This is a really fantastic shot, yet it feels like the whole image itself is the subject. Maybe I just have a different interpretation of what "Without Subject" means.', '2006-09-01 09:51:57.000000', NULL, 1),
(2782552, 386394, 21430, '<td valign="top">With the green spot dead center in the frame, my eyes are drawn straight to the center of the shot. It''s a good concept, I am just drawn to the center of the image, instead of the entire image.</td>', 'With the green spot dead center in the frame, my eyes are drawn straight to the center of the shot. It''s a good concept, I am just drawn to the center of the image, instead of the entire image.', '2006-09-01 09:54:44.000000', NULL, 1),
(2782615, 385678, 56474, '<td valign="top">Beautiful!</td>', 'Beautiful!', '2006-09-01 10:11:43.000000', NULL, 1),
(2782624, 386853, 56474, '<td valign="top">Very unique photo!</td>', 'Very unique photo!', '2006-09-01 10:13:54.000000', NULL, 1),
(2782627, 386767, 56474, '<td valign="top">Looks like Como park</td>', 'Looks like Como park', '2006-09-01 10:15:04.000000', NULL, 1),
(2782635, 385872, 56474, '<td valign="top">I really like this photo, looks like a piece of art created by one of the masters!! For some reason, I am drawn to this picture??</td>', 'I really like this photo, looks like a piece of art created by one of the masters!! For some reason, I am drawn to this picture??', '2006-09-01 10:17:53.000000', NULL, 1),
