(2788224, 386765, 43714, '<td valign="top">Looks scary, but I like it.</td>', 'Looks scary, but I like it.', '2006-09-02 12:58:54.000000', NULL, 1),
(2788234, 386474, 43714, '<td valign="top">I don''t know what these are but it''s different, like it.</td>', 'I don''t know what these are but it''s different, like it.', '2006-09-02 13:00:39.000000', NULL, 1),
(2788581, 386834, 48541, '<td valign="top">the colors in this picture are great. 9.</td>', 'the colors in this picture are great. 9.', '2006-09-02 14:56:37.000000', NULL, 1),
(2788594, 386765, 21026, '<td valign="top">Looks to much like my old windows wallpaper, but I still like it.</td>', 'Looks to much like my old windows wallpaper, but I still like it.', '2006-09-02 14:59:37.000000', NULL, 1),
(2788641, 385872, 50695, '<td valign="top">beautiful and I can''t wait to see how you kept from being dq''d. 9</td>', 'beautiful and I can''t wait to see how you kept from being dq''d. 9', '2006-09-02 15:20:59.000000', NULL, 1),
(2788642, 386715, 50695, '<td valign="top">painterly with a dynamic/mathematical abstract quality that few painters dare. 9</td>', 'painterly with a dynamic/mathematical abstract quality that few painters dare. 9', '2006-09-02 15:21:04.000000', NULL, 1),
(2788644, 383662, 50695, '<td valign="top">love the solid feel of the waves, they look like granite! 9</td>', 'love the solid feel of the waves, they look like granite! 9', '2006-09-02 15:21:32.000000', NULL, 1),
(2788647, 384302, 50695, '<td valign="top">one of the great debates of the 20th century. Pollock claimed to have carefully controlled every splash of paint, while Max Ernst openly experimented with randomness. your down-the-middle composition seems to embody the debate. 9</td>', 'one of the great debates of the 20th century. Pollock claimed to have carefully controlled every splash of paint, while Max Ernst openly experimented with randomness. your down-the-middle composition seems to embody the debate. 9', '2006-09-02 15:23:20.000000', NULL, 1),
(2788648, 386652, 50695, '<td valign="top">beautiful layered cascade of green leading to the suprise new world in the window. 9</td>', 'beautiful layered cascade of green leading to the suprise new world in the window. 9', '2006-09-02 15:24:02.000000', NULL, 1),
(2788670, 386860, 50695, '<td valign="top">appropriate title, the layers seem vast. a nice composition of light and darkness. 9</td>', 'appropriate title, the layers seem vast. a nice composition of light and darkness. 9', '2006-09-02 15:33:41.000000', NULL, 1),
(2788672, 386476, 50695, '<td valign="top">not sure I agree with the extreme DOF, but it is a bold choice, and an appropriate one for this challenge. interesting composition and great high contrast. 8</td>', 'not sure I agree with the extreme DOF, but it is a bold choice, and an appropriate one for this challenge. interesting composition and great high contrast. 8', '2006-09-02 15:35:40.000000', NULL, 1),
(2788680, 384781, 50695, '<td valign="top">well done. the high contrast creates little iconic trees, tractors and bales of hay. nice curvy composition as well. 9</td>', 'well done. the high contrast creates little iconic trees, tractors and bales of hay. nice curvy composition as well. 9', '2006-09-02 15:37:48.000000', NULL, 1),
(2788682, 386373, 50695, '<td valign="top">I love the simple composition and how the vegetation blurs into the corner. 8</td>', 'I love the simple composition and how the vegetation blurs into the corner. 8', '2006-09-02 15:38:44.000000', NULL, 1),
(2788684, 386260, 50695, '<td valign="top">I love how this simply IS, and it IS high contrast yet full detailed. A chalky paradise. 9</td>', 'I love how this simply IS, and it IS high contrast yet full detailed. A chalky paradise. 9', '2006-09-02 15:39:31.000000', NULL, 1),
(2788689, 386501, 50695, '<td valign="top">I love this literal yet creative interpretation of the challenge, and it is perfecty executed. The fence becomes an antagonistic symbol of everything it is blocking from us. 9</td>', 'I love this literal yet creative interpretation of the challenge, and it is perfecty executed. The fence becomes an antagonistic symbol of everything it is blocking from us. 9', '2006-09-02 15:40:29.000000', NULL, 1),
(2788710, 385346, 50695, '<td valign="top">This reminds me of my picture:<br/> <br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=366766" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/50695/thumb/366766.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/50695/thumb/366766.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/50695/thumb/366766.jpg"/></a> <br/> <br/>though your picture is more beautiful to look at. I was more concerned with symbolism. For some reason, I''m thinking about the Wizard of Oz. 9</td>', 'This reminds me of my picture:   though your picture is more beautiful to look at. I was more concerned with symbolism. For some reason, I''m thinking about the Wizard of Oz. 9', '2006-09-02 15:50:44.000000', NULL, 1),
(2788714, 386815, 50695, '<td valign="top">I love the composition, the white crest and the dark crest... the s curve... the lacy foam. 8</td>', 'I love the composition, the white crest and the dark crest... the s curve... the lacy foam. 8', '2006-09-02 15:51:42.000000', NULL, 1),
(2788719, 385792, 50695, '<td valign="top">good abstract study of reds and greens, with lots of lines as well. 8</td>', 'good abstract study of reds and greens, with lots of lines as well. 8', '2006-09-02 15:52:22.000000', NULL, 1),
(2788720, 386363, 50695, '<td valign="top">painterly. 8</td>', 'painterly. 8', '2006-09-02 15:52:37.000000', NULL, 1),
(2788722, 386662, 50695, '<td valign="top">good, bold abstract. 8</td>', 'good, bold abstract. 8', '2006-09-02 15:52:57.000000', NULL, 1),
(2788728, 385835, 50695, '<td valign="top">I love the way I can see each individual tree, but can also see them as one surface. Fantastic texture! 8</td>', 'I love the way I can see each individual tree, but can also see them as one surface. Fantastic texture! 8', '2006-09-02 15:53:58.000000', NULL, 1),
(2788735, 386579, 50695, '<td valign="top">terrific calligraphic composition. I enjoy the disorienting oof on the middle stone. 8</td>', 'terrific calligraphic composition. I enjoy the disorienting oof on the middle stone. 8', '2006-09-02 15:55:04.000000', NULL, 1),
(2788742, 386394, 50695, '<td valign="top">I like the way the sharply-defined circle in the almost-center mocks the notion of subject. And nice colors, too! I think you found just the right amount of sharpness. 8</td>', 'I like the way the sharply-defined circle in the almost-center mocks the notion of subject. And nice colors, too! I think you found just the right amount of sharpness. 8', '2006-09-02 15:56:49.000000', NULL, 1),
(2788745, 386710, 50695, '<td valign="top">the whole picture looks like a multi-faceted gem. 8</td>', 'the whole picture looks like a multi-faceted gem. 8', '2006-09-02 15:57:26.000000', NULL, 1),
(2788747, 386379, 50695, '<td valign="top">a universe in the nail polish. genius! 9</td>', 'a universe in the nail polish. genius! 9', '2006-09-02 15:57:45.000000', NULL, 1),
(2788748, 385901, 50695, '<td valign="top">a lovely study of white! 8</td>', 'a lovely study of white! 8', '2006-09-02 15:58:14.000000', NULL, 1),
(2788753, 386717, 50695, '<td valign="top">hilarious, very clever and perfectly executed. 8</td>', 'hilarious, very clever and perfectly executed. 8', '2006-09-02 15:59:01.000000', NULL, 1),
(2788756, 384429, 50695, '<td valign="top">I love the rising tower of vegetation next to the red guitar, and that terrific expanse of brick. the mural is purely secondary! Ah, I get it... no subject! 8</td>', 'I love the rising tower of vegetation next to the red guitar, and that terrific expanse of brick. the mural is purely secondary! Ah, I get it... no subject! 8', '2006-09-02 16:00:00.000000', NULL, 1),
(2788758, 386597, 50695, '<td valign="top">shimmery dynamic abstract. 8</td>', 'shimmery dynamic abstract. 8', '2006-09-02 16:00:23.000000', NULL, 1),
(2788760, 386657, 50695, '<td valign="top">great variations in tone, great composition, a successful abstract. 8</td>', 'great variations in tone, great composition, a successful abstract. 8', '2006-09-02 16:00:45.000000', NULL, 1),
(2788765, 386311, 50695, '<td valign="top">at first we think we know who the subject is, but then we realize he is framing another subject, who looks on blankly at his pain... or is that sympathy sneaking into his eyes? 8</td>', 'at first we think we know who the subject is, but then we realize he is framing another subject, who looks on blankly at his pain... or is that sympathy sneaking into his eyes? 8', '2006-09-02 16:01:54.000000', NULL, 1),
(2788770, 386661, 50695, '<td valign="top">classic composition with nice details on each of your two elements and nice texture on the wall. 8</td>', 'classic composition with nice details on each of your two elements and nice texture on the wall. 8', '2006-09-02 16:03:16.000000', NULL, 1),
(2788774, 386417, 50695, '<td valign="top">I love that distracting foreground element (shadow?). Great way to fulfill the challenge. 8</td>', 'I love that distracting foreground element (shadow?). Great way to fulfill the challenge. 8', '2006-09-02 16:03:52.000000', NULL, 1),
(2788777, 386589, 50695, '<td valign="top">great texture/rhythm, rich darkness, 8</td>', 'great texture/rhythm, rich darkness, 8', '2006-09-02 16:04:19.000000', NULL, 1),
(2788781, 383733, 50695, '<td valign="top">love your composition and the way this ugly form "rises" with a dramatic glow behind it. visually exciting. Why not make it bigger? 9</td>', 'love your composition and the way this ugly form "rises" with a dramatic glow behind it. visually exciting. Why not make it bigger? 9', '2006-09-02 16:05:34.000000', NULL, 1),
(2788783, 386402, 50695, '<td valign="top">Love this conceptual attack on the challenge. Funny but just wacky enough to be intellectually stimulating. 8</td>', 'Love this conceptual attack on the challenge. Funny but just wacky enough to be intellectually stimulating. 8', '2006-09-02 16:06:20.000000', NULL, 1),
(2788785, 386711, 50695, '<td valign="top">great dynamic lines. 8</td>', 'great dynamic lines. 8', '2006-09-02 16:06:35.000000', NULL, 1),
(2788789, 386686, 50695, '<td valign="top">those leaves are so... curly... dying yet vivid... the composition as a whole works on an abstract level at the same time. so sensual! 8</td>', 'those leaves are so... curly... dying yet vivid... the composition as a whole works on an abstract level at the same time. so sensual! 8', '2006-09-02 16:08:01.000000', NULL, 1);
