(2795140, 385243, 46314, '<td valign="top">This one is my favourite of the challenge. An inspired choice for an image without subject, and brilliantly executed too. Shows how interesting colour and texture can be by themselves. Well done.</td>', 'This one is my favourite of the challenge. An inspired choice for an image without subject, and brilliantly executed too. Shows how interesting colour and texture can be by themselves. Well done.', '2006-09-04 06:44:12.000000', NULL, 0),
(2795147, 386740, 52549, '<td valign="top">Very beautiful, huge congrats on the red.</td>', 'Very beautiful, huge congrats on the red.', '2006-09-04 06:51:15.000000', NULL, 0),
(2795150, 385243, 52549, '<td valign="top">Congratulations on your first ribbon! I love this image, great idea and beautiful colours.</td>', 'Congratulations on your first ribbon! I love this image, great idea and beautiful colours.', '2006-09-04 06:52:25.000000', NULL, 0),
(2795152, 385453, 37719, '<td valign="top">Very nice lines and balance in this picture.  Composition is excellent allowing both to come together in full strength.  The natural lighting also lends a lot of strength to the scene - the shift from left to right.  Very beautiful and serene setting captured very well.  The road and fence lines are really strong and well placed in the shot.  They really draw you into the scene and help you get absorbed in the peace of the location.  Very well shot Jimmy!  Good strong colors, good composition, great mood and emotive force!<br/><br/><i>Message edited by author 2006-09-04 05:56:09.</i></td>', 'Very nice lines and balance in this picture.  Composition is excellent allowing both to come together in full strength.  The natural lighting also lends a lot of strength to the scene - the shift from left to right.  Very beautiful and serene setting captured very well.  The road and fence lines are really strong and well placed in the shot.  They really draw you into the scene and help you get absorbed in the peace of the location.  Very well shot Jimmy!  Good strong colors, good composition, great mood and emotive force!', '2006-09-04 06:55:12.000000', '2006-09-04 06:56:09.000000', 0),
(2795161, 386831, 24613, '<td valign="top">Congrats Sammie!!  This is a great shot and well deserving of the blue.  Keep up the excellent work and you''re going to need a dump truck to haul off all the ribbons!! :)</td>', 'Congrats Sammie!!  This is a great shot and well deserving of the blue.  Keep up the excellent work and you''re going to need a dump truck to haul off all the ribbons!! :)', '2006-09-04 07:02:56.000000', NULL, 0),
