INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2795439, 386338, 62187, '<td valign="top">After reading your comments about your photo...I have to say this. Don''t be so hard on yourself. You nailed the challenge but the voters don''t see that. They picked pretty pictures, most of them with obvious subjects...imho...yours should have been in the top 15. Keep up the good work!</td>', 'After reading your comments about your photo...I have to say this. Don''t be so hard on yourself. You nailed the challenge but the voters don''t see that. They picked pretty pictures, most of them with obvious subjects...imho...yours should have been in the top 15. Keep up the good work!', '2006-09-04 09:34:29.000000', NULL, 0),
